using System;
using System.IO;
using System.Text;
using System.Web;
using System.Configuration;
using System.Collections.Generic;
using System.Security.Cryptography;

namespace PdfGen.Core
{
    public class PdfRenderConfig
    {
        public string OutputEncoding { get; set; }
        public bool AllowExternalResources { get; set; }
        public string BaseDirectory { get; set; }
        public int MaxDepth { get; set; }

        public static PdfRenderConfig FromEnvironment()
        {
            var config = new PdfRenderConfig
            {
                OutputEncoding = Environment.GetEnvironmentVariable("PDF_OUTPUT_ENCODING") ?? "utf-8",
                AllowExternalResources = false,
                BaseDirectory = AppDomain.CurrentDomain.BaseDirectory,
                MaxDepth = 3
            };
            return config;
        }
    }

    public class ContentSanitizer
    {
        private static readonly HashSet<string> AllowedSchemes = new HashSet<string>(
            new[] { "http", "https", "mailto" },
            StringComparer.OrdinalIgnoreCase);

        private readonly Encoding _processingEncoding;

        public ContentSanitizer(PdfRenderConfig config)
        {
            _processingEncoding = Encoding.UTF8;
        }

        public string SanitizeHtmlContent(string rawHtml)
        {
            if (string.IsNullOrEmpty(rawHtml))
                return string.Empty;

            // Phase 1: Normalize to processing encoding
            byte[] rawBytes = _processingEncoding.GetBytes(rawHtml);
            string normalized = _processingEncoding.GetString(rawBytes);

            // Phase 2: Strip dangerous tags
            normalized = StripScriptTags(normalized);
            normalized = StripEventHandlers(normalized);

            // Phase 3: Validate and neutralize URLs
            normalized = NeutralizeUrls(normalized);

            // Phase 4: All sanitization done in UTF-8; no transcoding step
            // Output remains in UTF-8 to prevent encoding differential attacks

            return normalized;
        }

        private string StripScriptTags(string input)
        {
            // Remove <script>...</script> blocks
            var result = System.Text.RegularExpressions.Regex.Replace(
                input, @"<script[^>]*>[\s\S]*?</script>",
                string.Empty,
                System.Text.RegularExpressions.RegexOptions.IgnoreCase);
            return result;
        }

        private string StripEventHandlers(string input)
        {
            // Remove on* event attributes
            var result = System.Text.RegularExpressions.Regex.Replace(
                input, @"\s+on\w+\s*=\s*([""'][^""']*[""']|\S+)",
                string.Empty,
                System.Text.RegularExpressions.RegexOptions.IgnoreCase);
            return result;
        }

        private string NeutralizeUrls(string input)
        {
            // Find href and src attributes, validate schemes
            var result = System.Text.RegularExpressions.Regex.Replace(
                input,
                @"((?:href|src)\s*=\s*[""'])([^""']+)([""'])",
                match => ValidateUrl(match),
                System.Text.RegularExpressions.RegexOptions.IgnoreCase);
            return result;
        }

        private string ValidateUrl(System.Text.RegularExpressions.Match match)
        {
            string prefix = match.Groups[1].Value;
            string url = match.Groups[2].Value;
            string suffix = match.Groups[3].Value;

            // Decode any percent-encoding for scheme check
            string decodedUrl = HttpUtility.UrlDecode(url, _processingEncoding);

            string trimmed = decodedUrl.TrimStart();

            // Relative URLs (no scheme) are allowed.
            int colonIdx = trimmed.IndexOf(':');
            int slashIdx = trimmed.IndexOf('/');
            bool hasScheme = colonIdx > 0 && (slashIdx == -1 || colonIdx < slashIdx);

            if (!hasScheme)
            {
                return match.Value;
            }

            string scheme = trimmed.Substring(0, colonIdx).Trim();

            // Allowlist: only explicitly permitted schemes pass through.
            if (AllowedSchemes.Contains(scheme))
            {
                return match.Value;
            }

            // Allow data URIs only for images (inline images).
            if (scheme.Equals("data", StringComparison.OrdinalIgnoreCase))
            {
                string rest = trimmed.Substring(colonIdx + 1).TrimStart();
                if (rest.StartsWith("image/", StringComparison.OrdinalIgnoreCase))
                {
                    return match.Value;
                }
            }

            // Anything not on the allowlist is blocked.
            return prefix + "#blocked" + suffix;
        }
    }

    public class PdfDocumentBuilder
    {
        private readonly PdfRenderConfig _config;
        private readonly ContentSanitizer _sanitizer;
        private readonly List<string> _pages;

        public PdfDocumentBuilder()
        {
            _config = PdfRenderConfig.FromEnvironment();
            _sanitizer = new ContentSanitizer(_config);
            _pages = new List<string>();
        }

        public void AddHtmlPage(string htmlContent)
        {
            string sanitized = _sanitizer.SanitizeHtmlContent(htmlContent);
            _pages.Add(sanitized);
        }

        public byte[] Render()
        {
            var sb = new StringBuilder();
            sb.AppendLine("%PDF-1.4");
            sb.AppendLine("1 0 obj<</Type/Catalog/Pages 2 0 R>>endobj");

            int pageCount = _pages.Count;
            sb.AppendLine($"2 0 obj<</Type/Pages/Kids[{GeneratePageRefs(pageCount)}]/Count {pageCount}>>endobj");

            int objNum = 3;
            foreach (var page in _pages)
            {
                sb.AppendLine($"{objNum} 0 obj<</Type/Page/Parent 2 0 R/Contents {objNum + 1} 0 R>>endobj");
                objNum++;
                string stream = ConvertHtmlToStream(page);
                sb.AppendLine($"{objNum} 0 obj<</Length {stream.Length}>>stream\n{stream}\nendstream endobj");
                objNum++;
            }

            sb.AppendLine("%%EOF");

            // Always output as UTF-8 to maintain sanitization integrity
            return Encoding.UTF8.GetBytes(sb.ToString());
        }

        private string GeneratePageRefs(int count)
        {
            var refs = new List<string>();
            int objNum = 3;
            for (int i = 0; i < count; i++)
            {
                refs.Add($"{objNum} 0 R");
                objNum += 2;
            }
            return string.Join(" ", refs);
        }

        private string ConvertHtmlToStream(string html)
        {
            // Simplified: embed HTML directly as PDF stream content
            return $"BT /F1 12 Tf ({EscapePdfString(html)}) Tj ET";
        }

        private string EscapePdfString(string input)
        {
            return input.Replace("\\", "\\\\").Replace("(", "\\(").Replace(")", "\\)");
        }
    }
